+const DANGEROUS_KEYS = new Set(["__proto__", "prototype", "constructor"]);
+
+function isDangerousKey(key) {
+  return DANGEROUS_KEYS.has(key);
+}
+
+function isPlainObject(value) {
+  if (typeof value !== "object" || value === null) return false;
+  if (Array.isArray(value)) return false;
+  if (value instanceof Date) return false;
+  const proto = Object.getPrototypeOf(value);
+  return proto === Object.prototype || proto === null;
+}
+
+// Deep-clones any value without aliasing mutable containers from the source,
+// stripping __proto__/prototype/constructor keys at every depth so cloned
+// patch data can never repoint Object.prototype.
+function cloneValue(value) {
+  if (Array.isArray(value)) {
+    return value.map(cloneValue);
+  }
+  if (value === null || typeof value !== "object") {
+    return value;
+  }
+  if (value instanceof Date) {
+    return new Date(value.getTime());
+  }
+  const proto = Object.getPrototypeOf(value);
+  const result = Object.create(proto);
+  for (const key of Object.keys(value)) {
+    if (isDangerousKey(key)) continue;
+    result[key] = cloneValue(value[key]);
+  }
+  return result;
+}
+
+function mergeValue(base, patch) {
+  if (isPlainObject(base) && isPlainObject(patch)) {
+    const result = {};
+    const keys = new Set([...Object.keys(base), ...Object.keys(patch)]);
+    for (const key of keys) {
+      if (isDangerousKey(key)) continue;
+      const inPatch = Object.prototype.hasOwnProperty.call(patch, key);
+      const inBase = Object.prototype.hasOwnProperty.call(base, key);
+      if (inPatch && inBase) {
+        result[key] = mergeValue(base[key], patch[key]);
+      } else if (inPatch) {
+        result[key] = cloneValue(patch[key]);
+      } else {
+        result[key] = cloneValue(base[key]);
+      }
+    }
+    return result;
+  }
+  return cloneValue(patch);
+}
